
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_op_pbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_op_pbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.913556019075951e-02, -5.883832306289674e-02, -5.839892493680952e-02, -5.774190042334996e-02, -5.674388439421147e-02, -5.519603915575801e-02, -5.273457834925318e-02, -4.873222006735047e-02, -4.228128677954079e-02, -3.318542723790695e-02, -2.579704003795131e-02, -2.934560598666914e-02, -3.525596814916961e-02, -2.792250771063478e-02, -1.723058249888783e-02, -7.626702598617284e-03, -2.541154563743645e-03, -6.178989191340649e-04, -7.980118528571134e-05, -4.513261493251363e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


